,p_static_id=>'thinking_detail'
,p_prompt=>'Thinking Detail'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'tools'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_attribute_group_id=>wwv_flow_imp.id(479228773849456090)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>How much text the thinking indicator shows next to the animation while an answer is being generated.</p>',
'',
'<ul>',
'  <li><strong>Off</strong> &mdash; the animation alone. Screen readers still get a status announcement.</li>',
'  <li><strong>Status</strong> &mdash; <code>Thinking&hellip;</code> plus the elapsed seconds.</li>',
'  <li><strong>Tools</strong> (default) &mdash; also says <code>Running a tool&hellip;</code> while a tool runs. The tool name is never shown here.</li>',
'</ul>',
'',
'<p>Tool names stay off the client unless the debug flag <code>show_tools</code> is set in <strong>Debug Config</strong>.</p>'))
);
