wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(497557018907137350)
,p_plugin_id=>wwv_flow_imp.id(865188135557955928)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>21
,p_display_sequence=>210
,p_static_id=>'widgets'
,p_prompt=>'Widgets'
,p_attribute_type=>'CHECKBOXES'
,p_is_required=>false
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_attribute_group_id=>wwv_flow_imp.id(479228396992456087)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Lets the AI show a small widget inside its answer instead of only text. Check the widget types you want to allow. Leave all boxes empty to keep answers as plain text.</p>',
'',
'<ul>',
'<li><strong>Stat card</strong>: one key figure with a label, unit, change and trend.</li>',
'<li><strong>Status</strong>: a notice with a level (ok, info, warn, error), a title and an optional text.</li>',
'<li><strong>Key value</strong>: a short list of label and value pairs.</li>',
'<li><strong>Table</strong>: rows from a tool result (at most 50 rows).</li>',
'<li><strong>Chart</strong>: a bar or line chart from a tool result (at most 200 points).</li>',
'</ul>',
'',
'<p>The server checks every widget. It keeps only known keys and bounded values. A widget that fails the check stays in the answer as text, and the turn does not fail. Table and chart data comes from the tool results of the same answer, so the AI does'
||' not retype the rows.</p>',
'',
'<p>Only the types you check here are described to the AI. The user cannot enable more. Types you added with your own code go in <strong>Custom Widgets</strong>.</p>',
'',
'<p>Requires the UC AI release 26.5. Default: <strong>none</strong>.</p>'))
);
