wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(497560001399164830)
,p_plugin_id=>wwv_flow_imp.id(865188135557955928)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>22
,p_display_sequence=>220
,p_static_id=>'custom_widgets'
,p_prompt=>'Custom Widgets'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(479228396992456087)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Widget types that were added to the plug-in with your own code, for example a list of files or orders. Enter the type names. Separate several names with a comma.</p>',
'',
'<p>A name works only when the type is registered in the table <code>UC_AI_CHAT_WIDGET_TYPES</code> and is enabled there. The plug-in ignores all other names. A wrong name does not cause an error: that one type stays off, and the APEX debug log shows '
||'a warning with the name.</p>',
'',
'<p>Each type you enter is described to the AI in the same way as the built-in types. The user cannot enable more. The built-in types stay in the attribute <strong>Widgets</strong>.</p>',
'',
'<p>Requires the UC AI release 26.5. Default: <strong>none</strong>.</p>'))
);
end;
/
